mapper.select:
select b.id, b.cfg_id, c.type as platform_type, b.oa_dept_id as oa_id, b.wx_dept_id, b.wx_dept_key, b.yx as bind_state, b.remark, b.modedatacreatedate as created_date, b.modedatacreatetime as created_time, b.modedatamodifydatetime as update_time, d.departmentname as oa_name, d.canceled as oa_canceled, d.supdepid as oa_parent_id, pd.departmentname as oa_parent_name, d.subcompanyid1 as oa_sub_id, s.subcompanyname as oa_sub_name, c.corp_name as cfg_name, c.corp_id, c.qy as cfg_enable, t.dept_name as wx_dept_name from ${deptBindTable} b left join hrmdepartment d on d.id = b.oa_dept_id left join hrmdepartment pd on pd.id = d.supdepid left join hrmsubcompany s on s.id = d.subcompanyid1 left join ${cfgTable} c on c.id = b.cfg_id left join ${deptTmpTable} t on t.corpid = c.corp_id and t.type = c.type and ((t.wx_dept_key is not null and t.wx_dept_key = b.wx_dept_key) or (t.wx_dept_key is null and t.wx_dept_id = b.wx_dept_id))
and b.yx = 1
and c.type = #{platform}
and b.cfg_id = #{cfgId}
and (d.departmentname like #{keyword} or s.subcompanyname like #{keyword} or c.corp_name like #{keyword} or b.wx_dept_id like #{keyword} or b.wx_dept_key like #{keyword} or t.dept_name like #{keyword})
order by c.type, b.cfg_id, s.subcompanyname, d.showorder, b.oa_dept_id

select b.id, b.cfg_id, c.type as platform_type, b.oa_user_id as oa_id, b.bind_state, b.bind_time, b.remark, b.modedatamodifydatetime as update_time, r.lastname as oa_name, r.loginid as oa_login_id, r.workcode as oa_workcode, r.mobile as oa_mobile, r.status as oa_status, r.departmentid as oa_dept_id, d.departmentname as oa_dept_name, d.subcompanyid1 as oa_sub_id, s.subcompanyname as oa_sub_name, c.corp_name as cfg_name, c.corp_id, c.qy as cfg_enable, b.x_user_id as wx_user_id, u.wx_name as wx_user_name, u.wx_dept_id as wx_user_dept_id, u.wx_dept_key as wx_user_dept_key, ut.dept_name as wx_user_dept_name from ${userBindTable} b left join hrmresource r on r.id = b.oa_user_id left join hrmdepartment d on d.id = r.departmentid left join hrmsubcompany s on s.id = d.subcompanyid1 left join ${cfgTable} c on c.id = b.cfg_id left join ${userTmpTable} u on u.corpid = c.corp_id and u.type = c.type and u.wx_user_id = b.x_user_id left join ${deptTmpTable} ut on ut.corpid = c.corp_id and ut.type = c.type and ((u.wx_dept_key is not null and ut.wx_dept_key = u.wx_dept_key) or (u.wx_dept_key is null and ut.wx_dept_key is null and ut.wx_dept_id = u.wx_dept_id))
and b.bind_state = 1
and c.type = #{platform}
and b.cfg_id = #{cfgId}
and (r.lastname like #{keyword} or r.loginid like #{keyword} or r.workcode like #{keyword} or b.x_user_id like #{keyword} or u.wx_name like #{keyword} or d.departmentname like #{keyword} or c.corp_name like #{keyword})
order by c.type, b.cfg_id, s.subcompanyname, d.showorder, b.oa_user_id
